INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0585f3da-0000-4000-8000-00000585f3da', '621491d3-0000-4000-8000-0000621491d3', 'PPL', 'airlaw', 'airlaw', 'Face-à-face et convergence', 2, 2, 'Vous volez vers le nord. Un avion motorisé ordinaire converge depuis l’est au même niveau, sans autre exception. Qui cède ?', 'You fly north. An ordinary powered aeroplane converges from the east at the same level, with no other exception. Who gives way?', '["L’autre, car vous êtes à sa gauche", "Celui dont le cap est le plus petit", "Celui qui vole vers l’ouest", "Vous, car il est à votre droite"]', '["The other, because you are on its left", "The aircraft with the smaller heading", "The aircraft flying west", "You, because it is on your right"]', 'Vous, car il est à votre droite', 'Identifier droite et gauche depuis le cockpit : le trafic venant de l’est est à droite du pilote orienté au nord.

![Priorités et prévention des collisions](/illustrations/ppl-airlaw-012.svg)', 'Identify sides from the cockpit: traffic from the east is on the right of a northbound pilot.

![PPL_AIRLAW_012](/illustrations/en/ppl-airlaw-012.svg)', '["PPL", "alignment-2026-09", "exam-mcq", "exam-subject:airlaw"]')
