INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0585f3db-0000-4000-8000-00000585f3db', '621491d3-0000-4000-8000-0000621491d3', 'PPL', 'airlaw', 'airlaw', 'Face-à-face et convergence', 2, 2, 'Vous êtes prioritaire mais la collision devient imminente. Que faire ?', 'You have right of way but collision becomes imminent. What should you do?', '["Attendre obligatoirement une clairance", "Fermer la radio pour se concentrer", "Agir pour éviter la collision", "Maintenir la trajectoire quoi qu’il arrive"]', '["Always wait for a clearance", "Switch off the radio to concentrate", "Act to avoid collision", "Maintain the flight path regardless"]', 'Agir pour éviter la collision', 'SERA.3201 maintient la responsabilité d’éviter une collision même lorsqu’on est prioritaire.

![Priorités et prévention des collisions](/illustrations/ppl-airlaw-012.svg)', 'SERA.3201 retains collision avoidance responsibility even with right of way.

![PPL_AIRLAW_012](/illustrations/en/ppl-airlaw-012.svg)', '["PPL", "alignment-2026-09", "exam-mcq", "exam-subject:airlaw"]')
