INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('03e33408-0000-4000-8000-000003e33408', '5aa89acb-0000-4000-8000-00005aa89acb', 'PPL', 'communications', 'communications', 'Reconnaître la panne et rechercher le contact', 2, 2, 'Au sol, un feu rouge continu est dirigé vers votre avion. Quelle action correspond au tableau ?', 'On the ground, a steady red light is directed at your aircraft. Which action matches the table?', '["Circuler avec prudence", "Arrêter", "Dégager l''aire d''atterrissage en service", "Revenir au point de départ"]', '["Taxi with caution", "Stop", "Vacate the landing area in use", "Return to starting point"]', 'Arrêter', 'Choisir la colonne au sol : rouge continu signifie arrêter. Dégager correspond aux éclats rouges ; revenir au départ aux éclats blancs. La couleur seule sans cadence ne suffit pas.

![Schéma / Diagram](/illustrations/ppl-com-002.svg)', 'Use the ground column: steady red means stop. Red flashes mean vacate; white flashes mean return to starting point. Colour without cadence is insufficient.

![Schéma / Diagram](/illustrations/en/ppl-com-002.svg)', '["PPL", "exam-mcq", "exam-subject:communications"]')
