INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('3a0e6dd9-0000-4000-8000-00003a0e6dd9', '4d9aff23-0000-4000-8000-00004d9aff23', 'PPL', 'human_performance', 'human_performance', 'Aptitude du jour', 1, 1, 'Une aptitude médicale valide garantit-elle une vigilance suffisante chaque jour ?', 'Does a valid medical guarantee sufficient alertness every day?', '["Oui après un café", "Non", "Oui", "Oui de jour"]', '["Yes, after coffee", "No", "Yes", "Yes, by day"]', 'Non', 'La fatigue et l''état de santé du jour doivent aussi être évalués.

![Évaluer l’état physique, la fatigue et la charge mentale avant le vol, puis adapter la décision à leur combinaison.](/illustrations/ppl-hp-001.svg)', 'Fatigue and health on the day must also be assessed.

![Diagram: Pilot fitness and physiological limitations](/illustrations/en/ppl-hp-001.svg)', '["human_performance", "PPL", "exam-mcq", "exam-subject:human_performance"]')
