INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('3a0e719b-0000-4000-8000-00003a0e719b', '4d9aff23-0000-4000-8000-00004d9aff23', 'PPL', 'human_performance', 'human_performance', 'Perception et altitude', 1, 1, 'Les sensations corporelles sont-elles toujours fiables sans horizon visible ?', 'Are bodily sensations always reliable without a visible horizon?', '["Non", "Oui", "Oui après quelques minutes", "Oui à faible vitesse"]', '["No", "Yes", "Yes, after a few minutes", "Yes, at low speed"]', 'Non', 'Le système sensoriel peut produire des illusions de mouvement et d''attitude.

![Évaluer l’état physique, la fatigue et la charge mentale avant le vol, puis adapter la décision à leur combinaison.](/illustrations/ppl-hp-001.svg)', 'The sensory system can create illusions of movement and attitude.

![Diagram: Pilot fitness and physiological limitations](/illustrations/en/ppl-hp-001.svg)', '["human_performance", "PPL", "exam-mcq", "exam-subject:human_performance"]')
