INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('2cfea899-0000-4000-8000-00002cfea899', '4d9aff25-0000-4000-8000-00004d9aff25', 'PPL', 'human_performance', 'human_performance', 'Hypoxie et monoxyde de carbone', 2, 2, 'En altitude, quelle évolution contribue à l’hypoxie ?', 'At altitude, which change contributes to hypoxia?', '["La baisse de pression partielle d’oxygène", "La disparition complète de l’azote", "L’augmentation systématique de l’oxygène", "La hausse du QNH imposée par la radio"]', '["Reduced oxygen partial pressure", "Complete disappearance of nitrogen", "Systematically increased oxygen", "A QNH rise imposed by radio"]', 'La baisse de pression partielle d’oxygène', 'La proportion d’oxygène varie peu ; sa pression partielle diminue.

![Respiration, vision et illusions](/illustrations/ppl-hp-003.svg)', 'The oxygen fraction changes little; its partial pressure decreases.

![PPL_HP_003](/illustrations/en/ppl-hp-003.svg)', '["PPL", "alignment-2026-09", "exam-mcq", "exam-subject:human_performance"]')
