INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('4d24cce0-0000-4000-8000-00004d24cce0', '555df131-0000-4000-8000-0000555df131', 'PPL', 'mass_and_balance', 'mass_and_balance', 'Lire une enveloppe fictive', 2, 2, 'Enveloppe fictive définie uniquement entre 700 et 850 kg : quelle masse maximale est couverte ?', 'A fictional envelope is defined only between 700 and 850 kg: what maximum mass is covered?', '["1 000 kg", "700 kg", "850 kg", "910 kg"]', '["1,000 kg", "700 kg", "850 kg", "910 kg"]', '850 kg', 'Le domaine fourni se termine à 850 kg. Cela décrit cet exercice ; ce nombre ne devient pas une masse maximale valable pour un avion réel.

![PPL_MB_002](/illustrations/ppl-mb-002.svg)', 'The supplied domain ends at 850 kg. This describes the exercise; the number does not become a maximum mass applicable to a real aircraft.

![PPL_MB_002](/illustrations/en/ppl-mb-002.svg)', '["PPL", "alignment-2026-09", "exam-mcq", "exam-subject:flight_performance_planning"]')
