INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('57754314-0000-4000-8000-000057754314', '555df131-0000-4000-8000-0000555df131', 'PPL', 'mass_and_balance', 'mass_and_balance', 'Consommation et déplacement de charge', 2, 2, '30 kg de carburant consommés au bras 1,50 m : moment à retirer ?', '30 kg fuel burned at arm 1.50 m: moment to subtract?', '["30 kg·m", "90 kg·m", "45 kg·m", "20 kg·m"]', '["30 kg·m", "90 kg·m", "45 kg·m", "20 kg·m"]', '45 kg·m', 'Moment retiré = 30 × 1,50 = 45 kg·m. 30 est la masse, pas le moment ; 90 correspondrait au moment des 60 kg initiaux.

![PPL_MB_002](/illustrations/ppl-mb-002.svg)', 'Removed moment = 30 × 1.50 = 45 kg·m. 30 is mass, not moment; 90 would be the moment of the initial 60 kg.

![PPL_MB_002](/illustrations/en/ppl-mb-002.svg)', '["PPL", "alignment-2026-09", "exam-mcq", "exam-subject:flight_performance_planning"]')
