INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('57754315-0000-4000-8000-000057754315', '555df131-0000-4000-8000-0000555df131', 'PPL', 'mass_and_balance', 'mass_and_balance', 'Consommation et déplacement de charge', 2, 2, 'Au départ 830 kg et 910 kg·m ; retrait de 30 kg et 45 kg·m, sans autre changement : centrage final ?', 'Initially 830 kg and 910 kg·m; remove 30 kg and 45 kg·m, with no other change: final CG?', '["Environ 1,138 m", "Environ 1,081 m", "Environ 1,096 m", "Environ 1,042 m"]', '["About 1.138 m", "About 1.081 m", "About 1.096 m", "About 1.042 m"]', 'Environ 1,081 m', 'Masse finale 800 kg, moment final 865 kg·m : 865/800 = 1,08125 m. 1,042 garderait l’ancienne masse ; 1,096 garderait l’ancien centrage.

![PPL_MB_002](/illustrations/ppl-mb-002.svg)', 'Final mass 800 kg, final moment 865 kg·m: 865/800 = 1.08125 m. 1.042 retains the old mass; 1.096 retains the old CG.

![PPL_MB_002](/illustrations/en/ppl-mb-002.svg)', '["PPL", "alignment-2026-09", "exam-mcq", "exam-subject:flight_performance_planning"]')
