INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('738080bc-0000-4000-8000-0000738080bc', '5af919a6-0000-4000-8000-00005af919a6', 'PPL', 'meteorology', 'meteorology', 'Altitude, hauteur et référence', 2, 2, 'Que signifie FL055 ?', 'What does FL055 mean?', '["5 500 ft vrais au-dessus de la mer dans toute atmosphère", "550 ft au QNH local", "5 500 ft au-dessus du relief", "5 500 ft sur la référence standard 1 013,25 hPa"]', '["5,500 ft true above sea level in every atmosphere", "550 ft on local QNH", "5,500 ft above terrain", "5,500 ft on the 1,013.25 hPa standard reference"]', '5 500 ft sur la référence standard 1 013,25 hPa', 'Le nombre d''un niveau de vol s''exprime en centaines de pieds sur la référence standard. Il ne décrit ni une hauteur terrain ni une altitude géométrique garantie.

![Recalage / Setting change](/illustrations/ppl-met-002.svg)', 'Flight level numbers represent hundreds of feet on the standard reference, not terrain height or guaranteed geometric altitude.

![Recalage / Setting change](/illustrations/en/ppl-met-002.svg)', '["PPL", "quiz-15-extension", "exam-mcq", "exam-subject:meteorology"]')
