INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('738080bd-0000-4000-8000-0000738080bd', '5af919a6-0000-4000-8000-00005af919a6', 'PPL', 'meteorology', 'meteorology', 'Altitude, hauteur et référence', 2, 2, 'Exercice sans erreurs atmosphériques : référence QFE à 650 ft AMSL et hauteur de 1 450 ft au-dessus de cette référence. Altitude AMSL ?', 'Exercise ignoring atmospheric errors: QFE datum 650 ft AMSL and height 1,450 ft above it. AMSL altitude?', '["1 450 ft", "650 ft", "2 100 ft", "800 ft"]', '["1,450 ft", "650 ft", "2,100 ft", "800 ft"]', '2 100 ft', 'Additionner altitude du datum et hauteur : 650+1450 = 2100 ft. Soustraire donne 800, qui ne correspond pas à la géométrie demandée.

![Recalage / Setting change](/illustrations/ppl-met-002.svg)', 'Add datum elevation and height: 650+1450 = 2100 ft. Subtraction gives 800, which does not match the requested geometry.

![Recalage / Setting change](/illustrations/en/ppl-met-002.svg)', '["PPL", "quiz-15-extension", "exam-mcq", "exam-subject:meteorology"]')
