INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('7611253d-0000-4000-8000-00007611253d', '5af919a7-0000-4000-8000-00005af919a7', 'PPL', 'meteorology', 'meteorology', 'Exemple d''interprétation', 1, 1, 'Un écart de 1 °C prouve-t-il la présence de brouillard ?', 'Does a 1 °C spread prove fog is present?', '["Oui", "Oui seulement à midi", "Oui au-dessus de la mer", "Non"]', '["Yes", "Yes, only at noon", "Yes, above the sea", "No"]', 'Non', 'Il faut vérifier les observations et les mécanismes de refroidissement.

