INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('535018fd-0000-4000-8000-0000535018fd', '37190244-0000-4000-8000-000037190244', 'PPL', 'performance', 'performance', 'Calculer une correction explicitement donnée', 2, 2, 'Que donne 520 m multiplié par 1,15 ?', 'What is 520 m multiplied by 1.15?', '["572 m", "650 m", "598 m", "535 m"]', '["572 m", "650 m", "598 m", "535 m"]', '598 m', 'La correction de l''exercice ajoute 15 % de 520, soit 78 m.

